/*
  src/components/PaperCard.jsx
  -----------------------------
  Displays ONE research paper as a card.

  WHY a separate component?
    The parent (ResultsList) renders MANY cards using .map()
    Each card is identical in structure but has different data.
    Perfect use case for a reusable component.

  PROPS RECEIVED:
    paper — one paper object from the API:
    {
      title: "Deep Learning for...",
      authors: ["Alice", "Bob"],
      year: 2023,
      abstract: "We propose...",
      citation_count: 142,
      url: "https://arxiv.org/...",
      ai_summary: "This paper proposes...",
      source: "arxiv"
    }

    index — the card's position (0, 1, 2...) used for animation delay
*/

import React, { useState } from 'react';
import { summarizePaper } from '../services/api';

function PaperCard({ paper, index }) {

  // Controls whether the abstract is expanded or collapsed
  const [expanded, setExpanded] = useState(false);

  // Tracks if we're loading an on-demand summary
  const [summaryLoading, setSummaryLoading] = useState(false);

  // Stores on-demand summary fetched by clicking "Summarize" button
  const [onDemandSummary, setOnDemandSummary] = useState(null);

  /*
    handleSummarize()
    ─────────────────
    Called when user clicks the "✨ Generate Summary" button.
    Sends the abstract to POST /api/papers/summarize.

    try/catch:
      try   → attempt something that might fail
      catch → handle the error gracefully (don't crash)

    finally → runs whether try succeeded or failed
              used here to always stop the loading spinner
  */
  const handleSummarize = async () => {
    if (!paper.abstract) return;
    setSummaryLoading(true);
    try {
      const result = await summarizePaper(paper.abstract);
      setOnDemandSummary(result.summary);
    } catch (err) {
      setOnDemandSummary('Could not generate summary. Check your HuggingFace token.');
    } finally {
      setSummaryLoading(false); // Always runs — stops spinner
    }
  };

  // The summary to display:
  // Priority: on-demand > from search > nothing
  const displaySummary = onDemandSummary || paper.ai_summary;

  // Truncate abstract for collapsed view — show first 200 chars
  const shortAbstract = paper.abstract
    ? paper.abstract.slice(0, 220) + (paper.abstract.length > 220 ? '...' : '')
    : null;

  /*
    formatAuthors()
    ───────────────
    Formats the authors array for display.
    ["Alice Smith", "Bob Jones", "Carol White", "Dave Brown"]
    →  "Alice Smith, Bob Jones, Carol White +1 more"

    Keeps it short to not overwhelm the card.
  */
  const formatAuthors = (authors) => {
    if (!authors || authors.length === 0) return 'Unknown authors';
    if (authors.length <= 3) return authors.join(', ');
    return `${authors.slice(0, 3).join(', ')} +${authors.length - 3} more`;
  };

  return (
    /*
      style={{ animationDelay }} staggers the card entrance animations.
      Card 0 appears immediately, card 1 after 0.05s, card 2 after 0.1s...
      Creates a smooth cascade effect as results load.
    */
    <div
      className="paper-card"
      style={{ animationDelay: `${index * 0.06}s` }}
    >

      {/* ── Header ── */}
      <div className="card-header">

        <div className="card-meta">
          {/* Source badge — shows "arXiv" or "Semantic Scholar" */}
          <span className={`source-badge source-${paper.source?.replace('_', '-')}`}>
            {paper.source === 'semantic_scholar' ? 'Semantic Scholar' : 'arXiv'}
          </span>

          {/* Year */}
          {paper.year && (
            <span className="year-badge">{paper.year}</span>
          )}

          {/* Citation count */}
          {paper.citation_count > 0 && (
            <span className="citation-badge">
              ⭐ {paper.citation_count.toLocaleString()} citations
              {/* toLocaleString() adds commas: 1842 → "1,842" */}
            </span>
          )}
        </div>

        {/* Paper title — clicking opens the paper URL */}
        {paper.url ? (
          <a
            href={paper.url}
            target="_blank"    // Open in new tab
            rel="noopener noreferrer"  // Security: prevents new tab from controlling this tab
            className="paper-title"
          >
            {paper.title}
          </a>
        ) : (
          <h3 className="paper-title no-link">{paper.title}</h3>
        )}

        {/* Authors */}
        <p className="paper-authors">
          👤 {formatAuthors(paper.authors)}
        </p>

      </div>

      {/* ── AI Summary Section ── */}
      {displaySummary && (
        <div className="summary-section">
          <div className="summary-label">
            🤖 AI Summary
            {/* Show "(extracted)" if it's the fallback, not real AI */}
            {displaySummary.startsWith('[Extracted]') && (
              <span className="extracted-tag"> · extracted</span>
            )}
          </div>
          <p className="summary-text">
            {/* Remove the [Extracted] prefix from display */}
            {displaySummary.replace('[Extracted] ', '')}
          </p>
        </div>
      )}

      {/* ── Abstract Section ── */}
      {paper.abstract && (
        <div className="abstract-section">
          <div className="abstract-label">Abstract</div>
          <p className="abstract-text">
            {/*
              Conditional rendering:
              expanded ? show full : show truncated

              The ternary operator: condition ? valueIfTrue : valueIfFalse
              Same as Python's: value_if_true if condition else value_if_false
            */}
            {expanded ? paper.abstract : shortAbstract}
          </p>

          {/* Only show toggle if abstract is long enough to truncate */}
          {paper.abstract.length > 220 && (
            <button
              className="toggle-abstract"
              onClick={() => setExpanded(!expanded)}
              // onClick={() => setExpanded(!expanded)
              // !expanded flips the boolean: true→false, false→true
            >
              {expanded ? '▲ Show less' : '▼ Read more'}
            </button>
          )}
        </div>
      )}

      {/* ── Footer: actions ── */}
      <div className="card-footer">

        {/* Show "Generate Summary" button only if no summary yet */}
        {!displaySummary && paper.abstract && (
          <button
            className="summarize-btn"
            onClick={handleSummarize}
            disabled={summaryLoading}
          >
            {summaryLoading ? (
              <><span className="spinner small"></span> Generating...</>
            ) : (
              '✨ Generate Summary'
            )}
          </button>
        )}

        {/* Link to paper */}
        {paper.url && (
          <a
            href={paper.url}
            target="_blank"
            rel="noopener noreferrer"
            className="read-paper-btn"
          >
            Read Paper →
          </a>
        )}

      </div>

    </div>
  );
}

export default PaperCard;
